async function verifyCaptcha(token, remoteIp) {
  const provider = process.env.CAPTCHA_PROVIDER ?? "hcaptcha";
  const secret = process.env.CAPTCHA_SECRET_KEY;
  if (!secret) return true;
  try {
    const url3 = provider === "recaptcha" ? "https://www.google.com/recaptcha/api/siteverify" : "https://hcaptcha.com/siteverify";
    const body = new URLSearchParams({ secret, response: token, remoteip: remoteIp });
    const resp = await fetch(url3, { method: "POST", body });
    const data = await resp.json();
    return data.success === true;
  } catch (error47) {
    console.error("[CAPTCHA] Verification failed:", error47);
    return false;
  }
}
